// Writes the PDF fonts in fonts/ into convex/pdf/fonts.ts as base64 text:
// Convex bundles only code, so the PDF module carries its font with it.
// Usage: bun scripts/embed-fonts.ts   (rerun after changing a font in fonts/)
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const fonts = {
  regular: "Geist-Regular.ttf",
  semiBold: "Geist-SemiBold.ttf",
} as const;

const base64 = (file: string) =>
  readFileSync(join(root, "fonts", file)).toString("base64");

const module = `"use node";

// Generated by scripts/embed-fonts.ts from fonts/; don't edit by hand.
// Geist, copyright (c) 2023 Vercel, in collaboration with basement.studio,
// under the SIL Open Font License 1.1 (fonts/OFL.txt).

/** The PDF typeface, as base64 TrueType files: Geist, the app's own. */
export const pdfFonts = {
${Object.entries(fonts)
  .map(([name, file]) => `  /** ${file} */\n  ${name}:\n    "${base64(file)}",`)
  .join("\n")}
};
`;

writeFileSync(join(root, "convex", "pdf", "fonts.ts"), module);
console.log("Wrote convex/pdf/fonts.ts");
